SELECT LOWER ("__policysql_t0"."name") AS "normalized_name", UPPER ("__policysql_t0"."name") AS "upper_name", JSON_EXTRACT ("__policysql_t0"."metadata", :path) AS "selected_metadata" FROM "projects" AS "__policysql_t0" WHERE ((("__policysql_t0"."name" GLOB :pattern) AND ("__policysql_t0"."name" LIKE :prefix)) AND ("__policysql_t0"."tenant_id" = :__policysql_session_tenant_id)) ORDER BY LOWER ("__policysql_t0"."name") ASC LIMIT MIN (:limit, 20) OFFSET :offset
